FUNCTION_BLOCK FB
VAR_INPUT
    openBtn   : BOOL;
    closeBtn  : BOOL;
    openLimit : BOOL;
    closeLimit: BOOL;
    obstacle  : BOOL;
END_VAR
VAR_OUTPUT
    motorUp   : BOOL := FALSE;
    motorDown : BOOL := FALSE;
    errorFlag : BOOL := FALSE;
END_VAR
VAR
    state       : INT := 0; // 0=IDLE, 1=OPENING, 2=CLOSING, 3=FAULT
    openBtnPrev : BOOL := FALSE;
    closeBtnPrev: BOOL := FALSE;
END_VAR

// 边沿检测
VAR
    openRising  : BOOL;
    closeRising : BOOL;
END_VAR
openRising  := openBtn  AND NOT openBtnPrev;
closeRising := closeBtn AND NOT closeBtnPrev;

// 更新历史
openBtnPrev  := openBtn;
closeBtnPrev := closeBtn;

// 复位逻辑（FAULT期间需同时按下两按钮）
IF state = 3 AND openBtn AND closeBtn THEN
    state := 0;
    errorFlag := FALSE;
END_IF

// 状态机逻辑
CASE state OF
    0: // IDLE
        motorUp   := FALSE;
        motorDown := FALSE;
        IF openRising AND NOT openLimit THEN
            state := 1; // → OPENING
        ELSIF closeRising AND NOT closeLimit THEN
            state := 2; // → CLOSING
        END_IF

    1: // OPENING
        motorUp   := TRUE;
        motorDown := FALSE;
        IF openLimit THEN
            state := 0; // 开到位，回IDLE
        ELSIF obstacle THEN
            motorUp   := FALSE;
            errorFlag := TRUE;
            state := 3; // 遇障，进入FAULT
        END_IF

    2: // CLOSING
        motorUp   := FALSE;
        motorDown := TRUE;
        IF closeLimit THEN
            state := 0; // 关到位，回IDLE
        ELSIF obstacle THEN
            motorDown := FALSE;
            state := 1; // 遇障，立即反向开门
        END_IF

    3: // FAULT
        motorUp   := FALSE;
        motorDown := FALSE;
        // 锁存，不自动恢复
END_CASE
END_FUNCTION_BLOCK
